/* The shape of the retrieval corpus. `src/corpus.json` is generated by
   `npm run corpus` from the site's own data, then bundled into the Worker, so
   ingest time and query time can never see different text. */

import data from './corpus.json' with { type: 'json' };

export type ChunkKind =
  | 'project'
  | 'experience'
  | 'moment'
  | 'about'
  | 'contact'
  | 'alibot'
  | 'readme';

export type Chunk = {
  /** Matches a `data-chunk` attribute on the site when `onPage` is true. */
  id: string;
  kind: ChunkKind;
  title: string;
  text: string;
  url: string;
  onPage: boolean;
};

export type Corpus = { builtAt: string; chunks: Chunk[] };

export const corpus = data as Corpus;
export const chunks: Chunk[] = corpus.chunks;

const index = new Map<string, Chunk>(chunks.map((c) => [c.id, c]));

export function byId(id: string): Chunk | undefined {
  return index.get(id);
}
